import heapq

def topo_order(nodes, edges):
    # Build the full set of nodes, including any that appear only in edges.
    all_nodes = set(nodes)
    for a, b in edges:
        all_nodes.add(a)
        all_nodes.add(b)

    # Initialize graph and indegree for every node.
    graph = {node: [] for node in all_nodes}
    indegree = {node: 0 for node in all_nodes}

    for a, b in edges:
        graph[a].append(b)
        indegree[b] += 1

    # Min-heap for available nodes, so we always pick the smallest string.
    heap = [node for node in all_nodes if indegree[node] == 0]
    heapq.heapify(heap)

    result = []

    while heap:
        node = heapq.heappop(heap)
        result.append(node)

        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    # If not all nodes were processed, there is a cycle.
    if len(result) != len(all_nodes):
        raise ValueError("cycle detected in graph")

    return result
